function updatePhysicalPort(item) {
  const id = `port-${item.name.replace('/', '-')}`;
  const wrapper = q(id);
  if (!wrapper) return;
  const status = ['up', 'down', 'disabled'].includes(item.status) ? item.status : 'unknown';
  wrapper.dataset.status = status;
  const label = wrapper.querySelector('.port-name');
  if (label) label.textContent = item.short;
  const shortAlias = STATIC_FIREWALL.shortPortLabels[item.name] || '';
  const aliasLabel = wrapper.querySelector('.port-alias-short');
  if (aliasLabel) {
    aliasLabel.textContent = shortAlias;
    aliasLabel.setAttribute('aria-hidden', shortAlias ? 'false' : 'true');
  }
  wrapper.dataset.linkName = shortAlias;
  const frame = wrapper.querySelector('.eth-frame');
  if (frame) {
    frame.classList.remove('up', 'down', 'disabled', 'unknown');
    frame.classList.add(status);
  }
  const stateText = status === 'up' ? 'UP' : status === 'down' ? 'DOWN' : status === 'disabled' ? 'DESABILITADA' : 'SEM DADOS';
  wrapper.title = `${item.name}${shortAlias ? ` (${shortAlias})` : ''} • ${stateText} • ${item.alias || 'Sem alias'} • IN ${formatBps(item.input)} • OUT ${formatBps(item.output)}`;
  wrapper.setAttribute('aria-label', wrapper.title);
}
for (const item of physical) updatePhysicalPort(item);

