function aggregateFrames(frameList, maxPoints = 120) {
  const usable = frameList.map(frame => ({values: valuesOf(frame).map(value => parseNumeric(value, null)), times: timesOf(frame)})).filter(entry => entry.values.some(Number.isFinite));
  if (!usable.length) return {values: [], times: []};
  const longest = usable.reduce((best, current) => current.values.length > best.values.length ? current : best, usable[0]);
  const length = Math.min(Math.max(...usable.map(entry => entry.values.length)), maxPoints);
  const values = [];
  const times = [];
  for (let point = 0; point < length; point++) {
    let sum = 0;
    let hasValue = false;
    for (const entry of usable) {
      const index = entry.values.length - length + point;
      const value = index >= 0 ? entry.values[index] : null;
      if (Number.isFinite(value)) { sum += value; hasValue = true; }
    }
    values.push(hasValue ? sum : 0);
    const timeIndex = longest.times.length - length + point;
    times.push(timeIndex >= 0 ? longest.times[timeIndex] : null);
  }
  return {values, times};
}
