function clearTrafficChart() {
  q('traffic-in-line')?.setAttribute('points', '');
  q('traffic-out-line')?.setAttribute('points', '');
  q('traffic-in-area')?.setAttribute('d', '');
  q('traffic-out-area')?.setAttribute('d', '');
  root.querySelectorAll('.axis-y, .axis-x span').forEach(element => { element.textContent = '—'; });
}
function renderTraffic(inValues, outValues, times) {
  if (!inValues.length && !outValues.length) { clearTrafficChart(); return; }
  const width = 700;
  const height = 160;
  const maximum = Math.max(1, ...inValues, ...outValues) * 1.08;
  const points = values => values.map((value, index) => [index / Math.max(1, values.length - 1) * width, height - value / maximum * (height - 8)]);
  const polyline = list => list.map(point => point.join(',')).join(' ');
  const area = list => list.length ? `M0 ${height} L${list.map(point => point.join(' ')).join(' L')} L${width} ${height} Z` : '';
  const inPoints = points(inValues);
  const outPoints = points(outValues);
  q('traffic-in-line')?.setAttribute('points', polyline(inPoints));
  q('traffic-out-line')?.setAttribute('points', polyline(outPoints));
  q('traffic-in-area')?.setAttribute('d', area(inPoints));
  q('traffic-out-area')?.setAttribute('d', area(outPoints));
  const grid = q('traffic-grid');
  if (grid && !grid.childElementCount) {
    for (let y = 0; y <= 4; y++) {
      const line = doc.createElementNS('http://www.w3.org/2000/svg', 'line');
      line.setAttribute('x1', 0); line.setAttribute('x2', width); line.setAttribute('y1', y * height / 4); line.setAttribute('y2', y * height / 4); line.setAttribute('class', 'grid-line'); grid.appendChild(line);
    }
    for (let x = 0; x <= 7; x++) {
      const line = doc.createElementNS('http://www.w3.org/2000/svg', 'line');
      line.setAttribute('y1', 0); line.setAttribute('y2', height); line.setAttribute('x1', x * width / 7); line.setAttribute('x2', x * width / 7); line.setAttribute('class', 'grid-line'); grid.appendChild(line);
    }
  }
  const steps = [maximum, maximum * 2 / 3, maximum / 3, 0];
  root.querySelectorAll('.axis-y').forEach((element, index) => { element.textContent = formatBps(steps[index]); });
  if (times.length) {
    const labels = root.querySelectorAll('.axis-x span');
    labels.forEach((element, index) => {
      const sourceIndex = Math.round(index * (times.length - 1) / Math.max(1, labels.length - 1));
      const date = new Date(times[sourceIndex]);
      element.textContent = Number.isNaN(date.getTime()) ? '—' : date.toLocaleTimeString('pt-BR', {hour: '2-digit', minute: '2-digit'});
    });
  }
}
renderTraffic(historicalIn.values, historicalOut.values, historicalIn.times.length ? historicalIn.times : historicalOut.times);

function spark(id, values) {
  const element = q(id);
  if (!element) return;
  const clean = (values || []).map(value => parseNumeric(value, null)).filter(Number.isFinite).slice(-40);
  if (!clean.length) { element.setAttribute('points', ''); return; }
  const minimum = Math.min(...clean);
  const maximum = Math.max(...clean);
  const span = Math.max(1, maximum - minimum);
  element.setAttribute('points', clean.map((value, index) => `${index / Math.max(1, clean.length - 1) * 130},${22 - (value - minimum) / span * 18}`).join(' '));
}
