const tableBody = q('interfaces-body');
if (tableBody) {
  const PAGE_SIZE = 10;

  const mgmtInterface = interfaces.find(item => String(item.name || '').toLowerCase() === 'mgmt') || null;
  const ethernetInterfaces = interfaces.filter(item => String(item.name || '').toLowerCase() !== 'mgmt');
  const pageCount = Math.max(1, Math.ceil(ethernetInterfaces.length / PAGE_SIZE));

  if (!root.__interfacePager) {
    root.__interfacePager = { page: 0, pauseUntil: 0, timer: null };
  }
  const pager = root.__interfacePager;
  pager.page = Math.max(0, Math.min(pageCount - 1, Number(pager.page || 0)));

  function appendInterfaceRow(item, isFixedMgmt = false) {
    const row = doc.createElement('tr');
    if (isFixedMgmt) row.classList.add('fixed-mgmt-row');

    const statusLabel = item.status === 'management' ? 'MGMT' : item.status === 'unknown' ? 'N/D' : item.status.toUpperCase();
    const errorClass = Number.isFinite(item.errors) && item.errors > 0 ? 'error-bad' : 'error-ok';
    const util = Number.isFinite(item.util) ? Math.max(0, Math.min(100, item.util)) : 0;

    row.innerHTML = `<td class="left">${item.name}</td><td class="center"><span class="table-status ${item.status}">${statusLabel}</span></td><td class="center">${item.type}</td><td class="left alias-cell" title="${escapeHtml(item.alias)}">${escapeHtml(item.alias)}</td><td class="center">${formatBps(item.speed)}</td><td class="center">${formatBps(item.input)}</td><td class="center">${formatBps(item.output)}</td><td class="center ${Number.isFinite(item.discards) ? 'error-ok' : ''}">${Number.isFinite(item.discards) ? formatNumber(item.discards, 2) : '—'}</td><td class="center ${errorClass}">${Number.isFinite(item.errors) ? formatNumber(item.errors, 2) : '—'}</td><td class="center"><div class="util-cell"><span>${Number.isFinite(item.util) ? `${formatNumber(item.util,1)}%` : '—'}</span><span class="util-bar"><i style="width:${util}%"></i></span></div></td>`;
    tableBody.appendChild(row);
  }

  function renderInterfacePage() {
    pager.page = ((pager.page % pageCount) + pageCount) % pageCount;
    tableBody.innerHTML = '';

    // MGMT permanece fixa no topo.
    if (mgmtInterface) appendInterfaceRow(mgmtInterface, true);

    // Demais interfaces são paginadas em blocos de 10.
    const startIndex = pager.page * PAGE_SIZE;
    const visibleInterfaces = ethernetInterfaces.slice(startIndex, startIndex + PAGE_SIZE);
    visibleInterfaces.forEach(item => appendInterfaceRow(item, false));

    setText('table-meta', `${interfaces.length} registros`);
    setText('if-page-indicator', `${pager.page + 1}/${pageCount}`);
  }

  const prevBtn = q('if-prev');
  const nextBtn = q('if-next');

  if (prevBtn) prevBtn.onclick = () => {
    pager.pauseUntil = Date.now() + 12000;
    pager.page -= 1;
    renderInterfacePage();
  };

  if (nextBtn) nextBtn.onclick = () => {
    pager.pauseUntil = Date.now() + 12000;
    pager.page += 1;
    renderInterfacePage();
  };

  renderInterfacePage();

  if (pager.timer) clearInterval(pager.timer);
  pager.timer = setInterval(() => {
    if (Date.now() < pager.pauseUntil || pageCount <= 1) return;
    pager.page += 1;
    renderInterfacePage();
  }, 8000);
}

